const body = $('Webhook').first().json.body || {};
const userId = body.userId || '';
const type = body.type || 'text';
const messages = [];
if (type === 'image') {
  const url = body.mediaUrl || '';
  if (!url) { throw new Error('Missing mediaUrl for image'); }
  messages.push({ type: 'image', originalContentUrl: url, previewImageUrl: body.mediaPreviewUrl || url });
} else if (type === 'video') {
  const url = body.mediaUrl || '';
  if (!url) { throw new Error('Missing mediaUrl for video'); }
  messages.push({ type: 'video', originalContentUrl: url, previewImageUrl: body.mediaPreviewUrl || url });
} else if (type === 'sticker') {
  const pkg = String(body.stickerPackage || '');
  const sid = String(body.stickerId || '');
  if (!pkg || !sid) { throw new Error('Missing sticker package/id'); }
  messages.push({ type: 'sticker', packageId: pkg, stickerId: sid });
} else {
  messages.push({ type: 'text', text: String(body.text || '') });
}
if (!userId) { throw new Error('Missing userId'); }
return [{ json: { to: userId, messages: messages } }];
